#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    int ways(vector<string>& pizza, int k) {
        const int MOD = 1e9 + 7;
        int m = pizza.size(), n = pizza[0].size();
        vector<vector<int>> pre(m + 1, vector<int>(n + 1));
        for (int i = m - 1; i >= 0; --i)
            for (int j = n - 1; j >= 0; --j)
                pre[i][j] = (pizza[i][j] == 'A') + pre[i + 1][j] + pre[i][j + 1] - pre[i + 1][j + 1];

        vector<vector<vector<int>>> dp(k, vector<vector<int>>(m, vector<int>(n)));
        for (int i = 0; i < m; ++i)
            for (int j = 0; j < n; ++j)
                dp[0][i][j] = pre[i][j] > 0;

        for (int l = 1; l < k; ++l)
            for (int i = 0; i < m; ++i)
                for (int j = 0; j < n; ++j) {
                    for (int ii = i + 1; ii < m; ++ii)
                        if (pre[i][j] - pre[ii][j] > 0)
                            dp[l][i][j] = (dp[l][i][j] + dp[l - 1][ii][j]) % MOD;
                    for (int jj = j + 1; jj < n; ++jj)
                        if (pre[i][j] - pre[i][jj] > 0)
                            dp[l][i][j] = (dp[l][i][j] + dp[l - 1][i][jj]) % MOD;
                }

        return dp[k - 1][0][0];
    }
};
